import{_ as t}from"./chunks/27-error-detail-modal.BExjAaM8.js";import{_ as r,o,c as n,a2 as d}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"Fehlercodes","description":"MiniTavern Fehlercodes bei Verbindungstest und Chat — Ursachen und Fixes (invalidApiKey, rateLimit, visionUnsupported …).","frontmatter":{"title":"Fehlercodes","description":"MiniTavern Fehlercodes bei Verbindungstest und Chat — Ursachen und Fixes (invalidApiKey, rateLimit, visionUnsupported …).","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Fehlercodes · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Fehlercodes bei Verbindungstest und Chat — Ursachen und Fixes (invalidApiKey, rateLimit, visionUnsupported …)."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/manual/errors"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/manual/errors"}]]},"headers":[],"relativePath":"de/manual/errors.md","filePath":"de/manual/errors.md","lastUpdated":1787224147000}'),i={name:"de/manual/errors.md"};function a(l,e,s,c,h,u){return o(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="fehlercodes" tabindex="-1">Fehlercodes <a class="header-anchor" href="#fehlercodes" aria-label="Permalink to &quot;Fehlercodes&quot;">​</a></h1><p>Bei fehlgeschlagenem Verbindungstest oder Chat-Bubble-Fehler <strong>Details</strong> öffnen und den <strong>Fehlercode</strong> (oder Textschlüsselwort) hier nachschlagen.</p><p>Details enthalten in der Regel:</p><ul><li><strong>Fehlercode</strong> (englische ID, z. B. <code>invalidApiKey</code>)</li><li><strong>Ursache</strong></li><li><strong>Fix-Vorschlag</strong></li></ul><p>Die «Codes» entsprechen den Klassennamen in der App-Detailansicht (i18n <code>llmTestError.*</code>).</p><hr><h2 id="schnellubersicht" tabindex="-1">Schnellübersicht <a class="header-anchor" href="#schnellubersicht" aria-label="Permalink to &quot;Schnellübersicht&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fehlercode</th><th>Kurz für Nutzer</th><th>Priorität</th></tr></thead><tbody><tr><td><code>missingApiKey</code></td><td>Bitte zuerst API Key eintragen</td><td>Key in der Modellverbindung</td></tr><tr><td><code>invalidApiKey</code></td><td>Key ungültig oder abgelaufen</td><td>vollständig kopieren; in der Konsole neu erzeugen</td></tr><tr><td><code>forbidden</code></td><td>Zugriff verweigert</td><td>Rechte, Modell freigeschaltet?</td></tr><tr><td><code>regionForbidden</code></td><td>Region nicht verfügbar</td><td>Netz / Proxy / internationale Site</td></tr><tr><td><code>network</code></td><td>Netzwerkfehler</td><td>Netz, Base URL, Firewall</td></tr><tr><td><code>timeout</code></td><td>Timeout</td><td>Netz; lokal Timeout erhöhen</td></tr><tr><td><code>modelNotFound</code></td><td>Modell existiert nicht</td><td>Modell-ID prüfen</td></tr><tr><td><code>modelRetired</code></td><td>Modell offline</td><td>aktuelles Modell aus der Liste</td></tr><tr><td><code>rateLimit</code></td><td>Zu häufig</td><td>warten und erneut</td></tr><tr><td><code>freeTierQuota</code></td><td>Free-Tier-Kontingent</td><td>laut Please retry in … warten; seltener oder Upgrade</td></tr><tr><td><code>insufficientQuota</code></td><td>Kontingent leer</td><td>aufladen / anderen Key</td></tr><tr><td><code>spendingCapExceeded</code></td><td>Monatliches Spend-Cap</td><td>Cap in der Konsole erhöhen</td></tr><tr><td><code>providerReturnedError</code></td><td>Upstream-Fehler</td><td>anderes Modell / anderes <code>:free</code> / OpenRouter BYOK</td></tr><tr><td><code>contextLengthExceeded</code></td><td>Kontext zu lang</td><td>Gedächtnis kürzen; Antwort-Token None; größeres Kontextmodell</td></tr><tr><td><code>anthropicMaxTokensRequired</code></td><td>Claude ohne max_tokens</td><td>«Antwort-Token» in Modelleinstellungen</td></tr><tr><td><code>badRequest</code></td><td>Parameterfehler</td><td>Parameter und Kompatibilitätsformat</td></tr><tr><td><code>serverError</code></td><td>Serverfehler</td><td>später erneut</td></tr><tr><td><code>requestFailed</code></td><td>Request fehlgeschlagen</td><td>Originaltext in Details</td></tr><tr><td><code>contentPolicy</code></td><td>Safety-Filter</td><td>neu generieren / Modell wechseln / umschreiben</td></tr><tr><td><code>emptyContent</code></td><td>Leere Antwort</td><td>erneut; Reasoning-Felder prüfen</td></tr><tr><td><code>modelAtCapacity</code></td><td>Modell ausgelastet</td><td>warten oder wechseln</td></tr><tr><td><code>productNotActivated</code></td><td>Produkt nicht freigeschaltet</td><td>in der Konsole aktivieren</td></tr><tr><td><code>visionUnsupported</code></td><td>Keine Bilder</td><td>Vision-Modell oder Anhänge aus</td></tr><tr><td><code>textOutputUnsupported</code></td><td>Kein Text-Chat</td><td>Textmodell wählen, keine TTS-/Bild-ID</td></tr></tbody></table><hr><h2 id="details-nach-kategorie" tabindex="-1">Details nach Kategorie <a class="header-anchor" href="#details-nach-kategorie" aria-label="Permalink to &quot;Details nach Kategorie&quot;">​</a></h2><h3 id="missingapikey" tabindex="-1">missingApiKey <a class="header-anchor" href="#missingapikey" aria-label="Permalink to &quot;missingApiKey&quot;">​</a></h3><ul><li><strong>Symptom</strong>: ohne Key kein Request.</li><li><strong>Fix</strong>: Einstellungen → Modellverbindung → API Key. Lokal Ollama usw. ggf. Platzhalter (wenn Nicht-leer geprüft wird).</li></ul><h3 id="invalidapikey" tabindex="-1">invalidApiKey <a class="header-anchor" href="#invalidapikey" aria-label="Permalink to &quot;invalidApiKey&quot;">​</a></h3><ul><li><strong>Symptom</strong>: 401, Key ungültig.</li><li><strong>Fix</strong>: ohne Leerzeichen kopieren; CN-/Intl.-Site und Key passen; Key neu erzeugen.</li></ul><h3 id="forbidden-regionforbidden" tabindex="-1">forbidden / regionForbidden <a class="header-anchor" href="#forbidden-regionforbidden" aria-label="Permalink to &quot;forbidden / regionForbidden&quot;">​</a></h3><ul><li><strong>Symptom</strong>: 403, Regionenlimit.</li><li><strong>Fix</strong>: Modellrechte; Proxy oder internationale Base URL.</li></ul><h3 id="network-timeout" tabindex="-1">network / timeout <a class="header-anchor" href="#network-timeout" aria-label="Permalink to &quot;network / timeout&quot;">​</a></h3><ul><li><strong>Symptom</strong>: keine Verbindung oder lange keine Antwort.</li><li><strong>Fix</strong>: <ul><li>Base URL (auf dem Handy kein <code>localhost</code> — LAN-IP des PCs).</li><li>Firewall-Ports; gleiches Wi‑Fi.</li><li>schwaches Netz oder langsames lokales Modell: Timeout hoch, kleineres Modell.</li></ul></li></ul><h3 id="modelnotfound" tabindex="-1">modelNotFound <a class="header-anchor" href="#modelnotfound" aria-label="Permalink to &quot;modelNotFound&quot;">​</a></h3><ul><li><strong>Symptom</strong>: falsche Modell-ID.</li><li><strong>Fix</strong>: nach Test aus Liste neu wählen; lokal wie <code>ollama list</code> / LM Studio-Name.</li></ul><h3 id="modelretired" tabindex="-1">modelRetired <a class="header-anchor" href="#modelretired" aria-label="Permalink to &quot;modelRetired&quot;">​</a></h3><ul><li><strong>Symptom</strong>: HTTP 404 mit <code>no longer available to new users</code> / <code>use a newer model</code> (z. B. <code>models/gemini-2.5-flash-lite</code>).</li><li><strong>Unterschied</strong>: vom Anbieter abgeschaltet oder nicht für neue Nutzer — kein Tippfehler.</li><li><strong>Fix</strong>: Liste aktualisieren, online Gemini wählen (z. B. <code>gemini-flash-latest</code>). Interactions API nicht nötig. Katalog: <a href="https://ai.google.dev/gemini-api/docs/models" target="_blank" rel="noreferrer">Gemini models</a>.</li></ul><h3 id="ratelimit" tabindex="-1">rateLimit <a class="header-anchor" href="#ratelimit" aria-label="Permalink to &quot;rateLimit&quot;">​</a></h3><ul><li><strong>Fix</strong>: seltener senden; warten; Plan upgraden.</li></ul><h3 id="freetierquota" tabindex="-1">freeTierQuota <a class="header-anchor" href="#freetierquota" aria-label="Permalink to &quot;freeTierQuota&quot;">​</a></h3><ul><li><strong>Symptom</strong>: Gemini u. a. <code>HTTP 429</code> + <code>generate_content_free_tier_requests</code> (oft limit: 20) mit <code>Please retry in …s</code>.</li><li><strong>Unterschied</strong>: Free <strong>RPM/RPD</strong>, nicht «kein Guthaben» und nicht Projekt-Spend-Cap.</li><li><strong>Fix</strong>: Sekunden laut Hinweis warten; Frequenz senken; <a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">AI Studio Usage</a>; höhere Limits über Billing/Upgrade. <a href="https://ai.google.dev/gemini-api/docs/rate-limits" target="_blank" rel="noreferrer">Gemini rate limits</a>.</li></ul><h3 id="insufficientquota-spendingcapexceeded" tabindex="-1">insufficientQuota / spendingCapExceeded <a class="header-anchor" href="#insufficientquota-spendingcapexceeded" aria-label="Permalink to &quot;insufficientQuota / spendingCapExceeded&quot;">​</a></h3><ul><li><strong>Unterschied</strong>: Kontingent leer vs. <strong>monatliches Projekt-Spend-Cap</strong> (später erneut oft nutzlos).</li><li><strong>Fix</strong>: aufladen; oder Cap in der Konsole (z. B. Google AI Studio Spend).</li></ul><h3 id="providerreturnederror" tabindex="-1">providerReturnedError <a class="header-anchor" href="#providerreturnederror" aria-label="Permalink to &quot;providerReturnedError&quot;">​</a></h3><ul><li><strong>Symptom</strong>: OpenRouter u. a. <code>HTTP 429: Provider returned error</code> (häufig bei <code>:free</code>).</li><li><strong>Fix</strong>: später; anderes freies Upstream; oder <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">OpenRouter BYOK</a>.</li></ul><h3 id="contextlengthexceeded" tabindex="-1">contextLengthExceeded <a class="header-anchor" href="#contextlengthexceeded" aria-label="Permalink to &quot;contextLengthExceeded&quot;">​</a></h3><ul><li><strong>Fix</strong>: Einstellungen → Modelleinstellungen → Gedächtnis kürzen; «Antwort-Token» auf None (falls sinnvoll); größeres Kontextmodell.</li></ul><h3 id="anthropicmaxtokensrequired" tabindex="-1">anthropicMaxTokensRequired <a class="header-anchor" href="#anthropicmaxtokensrequired" aria-label="Permalink to &quot;anthropicMaxTokensRequired&quot;">​</a></h3><ul><li><strong>Fix</strong>: Claude braucht max_tokens → «Antwort-Token» an, nicht None.</li></ul><h3 id="badrequest" tabindex="-1">badRequest <a class="header-anchor" href="#badrequest" aria-label="Permalink to &quot;badRequest&quot;">​</a></h3><ul><li><strong>Fix</strong>: Temperature usw.; echte OpenAI-/Anthropic-Kompatibilität des Gateways.</li></ul><h3 id="servererror-requestfailed-modelatcapacity" tabindex="-1">serverError / requestFailed / modelAtCapacity <a class="header-anchor" href="#servererror-requestfailed-modelatcapacity" aria-label="Permalink to &quot;serverError / requestFailed / modelAtCapacity&quot;">​</a></h3><ul><li><strong>Fix</strong>: später; Endpoint/Modell wechseln; bei Dauerfehler Anbieter mit Detailtext kontaktieren.</li></ul><h3 id="contentpolicy" tabindex="-1">contentPolicy <a class="header-anchor" href="#contentpolicy" aria-label="Permalink to &quot;contentPolicy&quot;">​</a></h3><ul><li><strong>Fix</strong>: neu generieren, umschreiben, lockereres Modell; manche NSFW-Karten triggern Output-Filter.</li></ul><h3 id="emptycontent" tabindex="-1">emptyContent <a class="header-anchor" href="#emptycontent" aria-label="Permalink to &quot;emptyContent&quot;">​</a></h3><ul><li><strong>Fix</strong>: erneut; manche Reasoning-Modelle liefern nur reasoning → Detailfelder oder anderes Modell.</li></ul><h3 id="productnotactivated" tabindex="-1">productNotActivated <a class="header-anchor" href="#productnotactivated" aria-label="Permalink to &quot;productNotActivated&quot;">​</a></h3><ul><li><strong>Fix</strong>: Produkt/Modell in der Cloud-Konsole freischalten, denselben Key weiter nutzen.</li></ul><h3 id="visionunsupported" tabindex="-1">visionUnsupported <a class="header-anchor" href="#visionunsupported" aria-label="Permalink to &quot;visionUnsupported&quot;">​</a></h3><ul><li><strong>Fix</strong>: Vision-Modell; oder keine Bilder / Bilderkennungs-Beschreibung als Text.</li></ul><h3 id="textoutputunsupported" tabindex="-1">textOutputUnsupported <a class="header-anchor" href="#textoutputunsupported" aria-label="Permalink to &quot;textOutputUnsupported&quot;">​</a></h3><ul><li><strong>Symptom</strong>: HTTP 400, <code>response modalities</code> und <code>TEXT</code> nicht unterstützt (z. B. <code>models/gemini-2.5-flash-preview-tts</code> nur <code>AUDIO</code>).</li><li><strong>Unterschied</strong>: TTS-/Bild-Spezialmodell für Chat-Test — kein Key-/Sampling-Fehler.</li><li><strong>Fix</strong>: Text-Chat-Modell (z. B. <code>gemini-flash-latest</code>). Keine IDs mit <code>tts</code> / <code>image</code>. Stimme/Bild in den jeweiligen Features konfigurieren.</li></ul><hr><h2 id="service-layer-codes-fortgeschritten" tabindex="-1">Service-Layer-Codes (fortgeschritten) <a class="header-anchor" href="#service-layer-codes-fortgeschritten" aria-label="Permalink to &quot;Service-Layer-Codes (fortgeschritten)&quot;">​</a></h2><p>Unten können <code>LlmErrorCode</code>-Werte in Logs / Dev erscheinen:</p><table tabindex="0"><thead><tr><th>Code</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>REQUEST_FAILED</code></td><td>nicht-streamender HTTP-Fehler</td></tr><tr><td><code>STREAM_FAILED</code></td><td>Stream-Fehler</td></tr><tr><td><code>REQUEST_CANCELLED</code></td><td>Nutzerabbruch</td></tr><tr><td><code>INVALID_CONFIG</code></td><td>ungültige Konfiguration</td></tr><tr><td><code>GET_MODELS_FAILED</code></td><td>Modellliste fehlgeschlagen</td></tr><tr><td><code>TEST_CONNECTION_FAILED</code></td><td>Verbindungstest fehlgeschlagen</td></tr><tr><td><code>PARSE_FAILED</code></td><td>Response-Parse fehlgeschlagen</td></tr><tr><td><code>UNKNOWN</code></td><td>unklassifiziert</td></tr></tbody></table><p>Nutzerseitig die Klassennamen oben priorisieren — diese Tabelle nicht auswendig lernen.</p><hr><h2 id="speziell-lokale-modelle" tabindex="-1">Speziell lokale Modelle <a class="header-anchor" href="#speziell-lokale-modelle" aria-label="Permalink to &quot;Speziell lokale Modelle&quot;">​</a></h2><p>PC Ollama / LM Studio nicht erreichbar: <a href="/ultra_guides/de/troubleshoot">Lokale Fehlerbehebung</a>.</p><p>App-Verbindungstest / Chat mit Fehlercode: <a href="/ultra_guides/de/manual/errors">Handbuch · Fehlercodes</a>.</p><div class="tip custom-block"><p class="custom-block-title">Screenshot</p><p><img src="'+t+'" alt="Fehlerdetails"></p></div>',58)])])}const f=r(i,[["render",a]]);export{m as __pageData,f as default};
